<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { message } from 'ant-design-vue'
import { usePortalStore } from '@/stores/portal'
import { iamMessage } from '@/services/iamAccess'
import { correctionEmployees, correctionList, correctionContext, createCorrection, updateCorrection, transitionCorrection, type Correction, type CorrectionAction, type CorrectionContext, type CorrectionEmployee } from '@/services/attendanceCorrections'
const portal=usePortalStore(),action=ref<CorrectionAction>('create'),employees=ref<CorrectionEmployee[]>([]),employee=ref(''),rows=ref<Correction[]>([]),loading=ref(false),busy=ref(false),error=ref(''),formOpen=ref(false),context=ref<CorrectionContext|null>(null),requestId=ref('')
const choices=[{value:'create',label:'登记草稿'},{value:'submit',label:'提交申请'},{value:'cancel',label:'取消已提交申请'},{value:'amend',label:'修订已取消申请'}] as const
const allowed=computed(()=>choices.filter(item=>portal.apps.find(app=>app.id==='attendance')?.accessCapabilities?.includes('attendance.correction.'+item.value)))
const fields=reactive({from_date:'',to_date:'',reason:'On Duty',explanation:'',half_day:false,half_day_date:'',include_holidays:false})
let generation=0
async function search(value=''){const run=++generation;employees.value=[];loading.value=true;error.value='';try{const data=await correctionEmployees(action.value,value);if(run===generation)employees.value=data.items}catch(e){if(run===generation)error.value=iamMessage(e)}finally{if(run===generation)loading.value=false}}
async function load(){const target=employee.value,mode=action.value,run=++generation;rows.value=[];if(!target)return;loading.value=true;error.value='';try{const data=await correctionList(target,mode);if(run===generation)rows.value=data.items}catch(e){if(run===generation)error.value=iamMessage(e)}finally{if(run===generation)loading.value=false}}
async function begin(row?:Correction){busy.value=true;error.value='';try{context.value=await correctionContext(employee.value,row?.amended_from?'amend':'create',row?.name);Object.assign(fields,{from_date:row?.from_date||'',to_date:row?.to_date||'',reason:row?.reason||'On Duty',explanation:row?.explanation||'',half_day:!!row?.half_day,half_day_date:row?.half_day_date||'',include_holidays:!!row?.include_holidays});requestId.value=crypto.randomUUID();formOpen.value=true}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
async function save(){if(!context.value||busy.value)return;busy.value=true;error.value='';try{const settings={...fields,half_day:fields.half_day?1:0,include_holidays:fields.include_holidays?1:0,...(!fields.half_day?{half_day_date:null}:{})};if(context.value.request)await updateCorrection(context.value.request.name,settings,context.value.request.modified,requestId.value);else await createCorrection(context.value.employee.name,context.value.employee.modified,settings,requestId.value);formOpen.value=false;message.success('更正草稿已登记，尚未提交。');await load()}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
const pending=ref<{row:Correction;action:CorrectionAction;requestId:string}|null>(null)
function prepare(row:Correction){const operation=action.value;if(operation==='create'||operation==='amend'&&row.docstatus===0){void begin(row);return;}pending.value={row,action:operation,requestId:crypto.randomUUID()}}
async function confirmTransition(){const command=pending.value;if(!command||busy.value)return;busy.value=true;error.value='';try{await transitionCorrection(command.row.name,command.action,command.row.modified,command.requestId);pending.value=null;message.success(command.action==='amend'?'修订草稿已创建，仍需核对并提交。':'原生更正状态已更新。');await load()}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}

watch(action,async()=>{employee.value='';rows.value=[];await search()})
onMounted(async()=>{if(!allowed.value.length)return;if(!allowed.value.some(row=>row.value===action.value)&&allowed.value[0])action.value=allowed.value[0].value;await search()})
</script>
<template><section class="corrections product-page app-product-page"><div class="glass-hero"><h1>考勤更正</h1><p>登记原生更正申请，核对事实说明，再按草稿、提交、取消、修订的顺序办理。</p></div><section class="glass-surface section-panel"><a-alert v-if="!allowed.length" type="info" message="当前角色没有获准的更正操作。"/><a-space v-else wrap><a-select v-model:value="action" aria-label="更正办理阶段" :options="allowed" style="min-width:180px"/><a-select v-model:value="employee" show-search :filter-option="false" :options="employees.map(row=>({value:row.name,label:row.employee_name+' · '+row.employee_number}))" :loading="loading" placeholder="搜索负责公司内的员工" aria-label="更正员工" style="min-width:300px" @search="search" @change="load"/><a-button v-if="action==='create'" type="primary" :disabled="!employee" :loading="busy" @click="begin()">登记更正</a-button><a-button :disabled="!employee" :loading="loading" @click="load">读取最新申请</a-button></a-space><a-alert v-if="error" :message="error" type="warning" show-icon/><a-table :data-source="rows" row-key="name" :loading="loading" :pagination="{pageSize:10}"><a-table-column title="申请" data-index="name"/><a-table-column title="开始日期" data-index="from_date"/><a-table-column title="结束日期" data-index="to_date"/><a-table-column title="事实说明" data-index="explanation"/><a-table-column title="状态" key="state"><template #default="{record}">{{['草稿','已提交','已取消'][record.docstatus]}}</template></a-table-column><a-table-column title="办理" key="action"><template #default="{record}"><a-button :disabled="busy" @click="prepare(record)">{{action==='create'||action==='amend'&&record.docstatus===0?'修改草稿':choices.find(row=>row.value===action)?.label}}</a-button></template></a-table-column></a-table></section><a-modal v-model:open="formOpen" :get-container="false" :title="context?.request ? '修改考勤更正草稿' : '登记考勤更正草稿'" :footer="null" :mask-closable="false"><p>{{context?.employee.employee_name}} · {{context?.employee.department}}</p><a-alert v-if="error" :message="error" type="warning"/><a-form layout="vertical" @submit.prevent="save"><a-form-item label="更正期间" required><a-space><a-input v-model:value="fields.from_date" type="date" aria-label="更正开始日期"/><a-input v-model:value="fields.to_date" type="date" aria-label="更正结束日期"/></a-space></a-form-item><a-form-item label="原生原因" required><a-select v-model:value="fields.reason" :options="[{value:'On Duty',label:'因公出勤'},{value:'Work From Home',label:'居家工作'}]"/></a-form-item><a-form-item label="事实说明" required><a-textarea v-model:value="fields.explanation" :maxlength="500" :rows="3"/></a-form-item><a-form-item><a-checkbox v-model:checked="fields.half_day">半天</a-checkbox><a-input v-if="fields.half_day" v-model:value="fields.half_day_date" type="date" aria-label="半天日期"/></a-form-item><a-form-item><a-checkbox v-model:checked="fields.include_holidays">包含休息日（按实际情况选择）</a-checkbox></a-form-item><a-button :disabled="busy" @click="formOpen=false">取消</a-button><a-button type="primary" html-type="submit" :loading="busy">保存草稿</a-button></a-form></a-modal><a-modal :open="!!pending" :get-container="false" :title="choices.find(row=>row.value===pending?.action)?.label" ok-text="确认办理" cancel-text="返回核对" :confirm-loading="busy" :mask-closable="false" @ok="confirmTransition" @cancel="pending=null"><p>{{pending?.row.from_date}} 至 {{pending?.row.to_date}} · {{pending?.row.explanation || pending?.row.reason}}</p><p>按原生状态与审批规则执行。</p><a-alert v-if="error" type="warning" :message="error"/></a-modal></section></template>
<style scoped>.corrections{display:grid;gap:20px}.glass-hero,.section-panel{padding:24px}.glass-hero h1{margin:0 0 12px}.ant-alert{margin:16px 0}.ant-btn+.ant-btn{margin-left:12px}.ant-table-wrapper{margin-top:20px}</style>
